import numpy as np

def problem(x: np.ndarray) -> float:
    """
    A synthetic 4-dimensional benchmark function designed to exhibit specific ELA features.

    This function combines a product of sigmoids with a non-separable term and an interaction term.

    Formula:
    f(x) = scale_sigmoid * product_of_sigmoids(x) + scale_nonsep * non_separable_term(x) + scale_interact * interaction_term(x)
    where:
        product_of_sigmoids(x) = product(sigmoid(x))
        non_separable_term(x) = sum(abs(x[i] - x[i+1])**3) for i=0 to 2
        interaction_term(x) = x[0]*x[1] + x[2]*x[3]

    Args:
        x (np.ndarray): A 1D NumPy array of shape (4,).

    Returns:
        float: The objective value.
    """
    x = np.asarray(x)

    def sigmoid(z):
        return 1 / (1 + np.exp(-z))

    def product_of_sigmoids(x):
        return np.prod(sigmoid(x))

    def non_separable_term(x):
        return np.sum(np.abs(x[:-1] - x[1:])**3)

    def interaction_term(x):
        return x[0]*x[1] + x[2]*x[3]

    scale_sigmoid = 0.6
    scale_nonsep = 0.3
    scale_interact = 0.1

    return scale_sigmoid * product_of_sigmoids(x) + scale_nonsep * non_separable_term(x) + scale_interact * interaction_term(x)
